import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        PriorityQueue<Integer> heap = new PriorityQueue<>(n, Collections.reverseOrder());
        for (int i = 0; i < n; i++) heap.add(nextInt());
        // Halve the largest pile each time; once the max is 1 nothing changes.
        for (int i = 0; i < k; i++) {
            int v = heap.peek();
            if (v == 1) break;
            heap.poll();
            heap.add((v + 1) / 2);
        }
        long total = 0;
        for (int v : heap) total += v;
        System.out.println(total);
    }
}

package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
	"sort"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

type maxHeap struct{ sort.IntSlice }

func (h maxHeap) Less(i, j int) bool { return h.IntSlice[i] > h.IntSlice[j] }
func (h *maxHeap) Push(x any)        { h.IntSlice = append(h.IntSlice, x.(int)) }
func (h *maxHeap) Pop() any {
	old := h.IntSlice
	x := old[len(old)-1]
	h.IntSlice = old[:len(old)-1]
	return x
}

func main() {
	n, k := readInt(), readInt()
	h := &maxHeap{make(sort.IntSlice, n)}
	for i := range h.IntSlice {
		h.IntSlice[i] = readInt()
	}
	heap.Init(h)
	// Halve the largest pile each time; once the max is 1 nothing changes.
	for i := 0; i < k; i++ {
		v := h.IntSlice[0]
		if v == 1 {
			break
		}
		h.IntSlice[0] = (v + 1) / 2
		heap.Fix(h, 0)
	}
	total := 0
	for _, v := range h.IntSlice {
		total += v
	}
	fmt.Println(total)
}
